```java
import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

/**
 * A class demonstrating proper, secure API use for file access.
 */
public class SafeFileAccessor {

    // The intended directory where user files are stored.
    private static final String BASE_DIRECTORY = "/var/www/uploads/";

    /**
     * Securely reads a file based on a user-provided filename.
     * @param filename The name of the file to read, provided by the user.
     * @return The byte content of the file.
     * @throws IOException If the file is outside the base directory or cannot be read.
     */
    public byte[] getFileContent(String filename) throws IOException {
        // Construct a File object representing the user's request.
        File requestedFile = new File(BASE_DIRECTORY, filename);

        // Get the canonical path, which resolves symbolic links, ".", and "..".
        String canonicalPath = requestedFile.getCanonicalPath();

        // Security Check: Ensure the resolved path is still within the intended base directory.
        // This is the crucial step that prevents the traversal attack.
        if (!canonicalPath.startsWith(new File(BASE_DIRECTORY).getCanonicalPath())) {
            throw new SecurityException("Access denied: File is outside of the allowed directory.");
        }

        // If the check passes, we can safely read and return the file content.
        return Files.readAllBytes(requestedFile.toPath());
    }
}
